import crypto from 'crypto'
import { db, sqliteDb } from '@/db/index.js'
import type Database from 'better-sqlite3'
import { sales, saleLineItems, payments, vatRates, paymentAllocations, stockMovements, sequences } from '@/db/schema.js'
import { desc, eq, inArray, sql, sum, asc } from 'drizzle-orm'
import { createDirectSaleInputSchema } from '@pi-skeleton/shared/validations/sales'
import { computeLineTotals } from '@shared/lib/pricing.js'

// ============================================================================
// Types
// ============================================================================

/** Input for creating a direct sale (validated via Zod schema) */
export interface CreateDirectSaleInput {
  /** Optional customer ID — null/absent means walk-in */
  customerId?: string | null
  /** Payment method */
  paymentMethod: 'cash' | 'card'
  /** Line items being purchased */
  lineItems: Array<{
    partId: string
    quantity: number
    unitPriceNet: number
    vatRateId: string
    description: string
    discountPercent?: number | null
  }>
}

/** Result returned after a successful sale creation */
export interface SaleResult {
  /** The created sale header */
  sale: typeof sales.$inferSelect
  /** The created payment record */
  payment: typeof payments.$inferSelect
  /** All line items for this sale */
  lineItems: typeof saleLineItems.$inferSelect[]
}

/** Error thrown when stock validation fails */
export class InsufficientStockError extends Error {
  constructor(public readonly shortfalls: Array<{ partId: string; requested: number; available: number }>) {
    super(`Insufficient stock for ${shortfalls.length} part(s)`)
    this.name = 'InsufficientStockError'
  }
}

/** Error thrown when a sale is not found */
export class SaleNotFoundError extends Error {
  constructor(public readonly id: string) {
    super(`Sale not found: ${id}`)
    this.name = 'SaleNotFoundError'
  }
}

// ============================================================================
// Stock validation — aggregates from stock_movements (no denormalized trust)
// ============================================================================

/** Input: one part with a requested quantity to validate. */
interface StockCheckRequest {
  /** Part ID to check availability for */
  partId: string
  /** Number of units the caller wants to sell */
  requestedQuantity: number
}

/** One part that does not have enough stock. */
interface ShortfallDetail {
  /** The part ID with insufficient stock */
  partId: string
  /** How many units were requested */
  requested: number
  /** How many units are actually available (computed from movements) */
  available: number
}

/** Result of validating a batch of stock requests. */
interface StockValidationResult {
  /** true if every part has sufficient stock; false otherwise */
  valid: boolean
  /** Non-empty only when valid is false — lists each short-falling part */
  shortfalls: ShortfallDetail[]
}

/**
 * Validate whether requested quantities are available in stock.
 *
 * Computes available stock per part by summing `quantityDelta` from the
 * `stock_movements` table — never trusts denormalized `quantityOnHand`.
 */
async function validateStockAvailability(
  requests: StockCheckRequest[]
): Promise<StockValidationResult> {
  if (requests.length === 0) {
    return { valid: true, shortfalls: [] }
  }

  const partIds = [...new Set(requests.map(r => r.partId))]

  const aggregationQuery = db
    .select({
      partId: stockMovements.partId,
      totalDelta: sql<number>`COALESCE(${sum(stockMovements.quantityDelta)}, 0)`
    })
    .from(stockMovements)
    .where(inArray(stockMovements.partId, partIds))
    .groupBy(stockMovements.partId)

  const aggregationResults = await aggregationQuery

  const availableMap = new Map<string, number>()
  for (const row of aggregationResults) {
    availableMap.set(row.partId, Number(row.totalDelta))
  }

  const shortfalls: ShortfallDetail[] = []
  for (const req of requests) {
    const available = availableMap.get(req.partId) ?? 0
    if (req.requestedQuantity > available) {
      shortfalls.push({
        partId: req.partId,
        requested: req.requestedQuantity,
        available
      })
    }
  }

  shortfalls.sort((a, b) => a.partId.localeCompare(b.partId))

  return {
    valid: shortfalls.length === 0,
    shortfalls
  }
}

// ============================================================================
// Sequence helper — atomic increment for document numbering
// ============================================================================

/**
 * Get the next sequential value for a document number sequence.
 * Atomically increments the counter and returns the new value.
 */
async function getNextValue(name: string): Promise<number> {
  const updateResult = await db
    .update(sequences)
    .set({ currentValue: sql`${sequences.currentValue} + 1` })
    .where(eq(sequences.name, name))

  if (updateResult.changes === 0) {
    await db.insert(sequences).values({ name, currentValue: 1 })
    return 1
  }

  const [row] = await db
    .select({ currentValue: sequences.currentValue })
    .from(sequences)
    .where(eq(sequences.name, name))

  return row!.currentValue
}

// ============================================================================
// Public API
// ============================================================================

/**
 * Create a direct sale atomically in a single database transaction.
 *
 * Flow: validate input → check stock → get sequence number → insert sale header
 *       → insert line items → insert payment → insert allocation → insert stock movements
 * All-or-nothing: any failure rolls back everything.
 *
 * @param rawInput — Unvalidated input object (will be validated via Zod)
 * @returns Sale result with created entities
 */
export async function createDirectSale(rawInput: unknown): Promise<SaleResult> {
  // Validate input via Zod schema
  const parsed = createDirectSaleInputSchema.safeParse(rawInput)
  if (!parsed.success) {
    throw new Error(`Invalid sale input: ${parsed.error.message}`)
  }

  const input = parsed.data as CreateDirectSaleInput

  // ---------------------------------------------------------------------------
  // Step 1: Validate stock availability for all line items
  // ---------------------------------------------------------------------------
  const stockRequests = input.lineItems.map((item) => ({
    partId: item.partId,
    requestedQuantity: item.quantity
  }))

  const stockResult = await validateStockAvailability(stockRequests)
  if (!stockResult.valid) {
    throw new InsufficientStockError(stockResult.shortfalls)
  }

  // ---------------------------------------------------------------------------
  // Step 2: Get sale number from sequence table (atomic increment)
  // ---------------------------------------------------------------------------
  const saleNumberSeq = await getNextValue('sale')
  const saleNumber = `SA-${String(saleNumberSeq).padStart(4, '0')}`

  // ---------------------------------------------------------------------------
  // Step 3: Fetch VAT rates needed for line item calculations
  // ---------------------------------------------------------------------------
  const allVatRates = await db.select({ id: vatRates.id, rate: vatRates.rate }).from(vatRates)
  const vatRatesMap = new Map<string, number>()
  for (const row of allVatRates) {
    vatRatesMap.set(row.id, Number(row.rate))
  }

  // ---------------------------------------------------------------------------
  // Step 4: Compute line item totals using shared pricing lib
  // ---------------------------------------------------------------------------
  const lineItemsData = input.lineItems.map((item) => {
    const vatRateBps = vatRatesMap.get(item.vatRateId) ?? 0
    const totals = computeLineTotals(item.unitPriceNet, item.quantity, item.discountPercent, vatRateBps)

    return {
      partId: item.partId,
      quantity: item.quantity,
      unitPriceNet: item.unitPriceNet,
      vatRateId: item.vatRateId,
      description: item.description,
      discountPercent: item.discountPercent ?? null,
      lineTotalNet: totals.net,
      lineTotalVat: totals.vat,
      lineTotalGross: totals.gross,
      lineType: 'part' as const
    }
  })

  const subtotalNet = lineItemsData.reduce((sum, item) => sum + item.lineTotalNet, 0)
  const vatTotal = lineItemsData.reduce((sum, item) => sum + item.lineTotalVat, 0)
  const totalGross = subtotalNet + vatTotal

  // ---------------------------------------------------------------------------
  // Step 5: Execute single transaction — all inserts or nothing
  // ---------------------------------------------------------------------------
  const saleId = crypto.randomUUID()
  const paymentId = crypto.randomUUID()

  const client = sqliteDb as Database.Database
  const run = (sqlStr: string, params?: unknown[]) => {
    return client.prepare(sqlStr).run(...(params ?? []))
  }

  try {
    // Begin transaction
    run('BEGIN TRANSACTION')

    // Insert sale header
    run(
      'INSERT INTO sales (id, sale_number, customer_id, source_type, source_id, status, subtotal_net, vat_total, total_gross, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)',
      [saleId, saleNumber, input.customerId ?? null, 'direct_sale', null, 'completed', subtotalNet, vatTotal, totalGross, Date.now()]
    )

    const now = Date.now()

    // Insert line items
    for (const item of lineItemsData) {
      const lineItemId = crypto.randomUUID()
      run(
        'INSERT INTO sale_line_items (id, sale_id, line_type, part_id, description, quantity, unit_price_net, vat_rate_id, discount_percent, line_total_net, line_total_vat, line_total_gross, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)',
        [lineItemId, saleId, item.lineType, item.partId, item.description, item.quantity, item.unitPriceNet, item.vatRateId, item.discountPercent, item.lineTotalNet, item.lineTotalVat, item.lineTotalGross, now]
      )
    }

    // Insert payment record
    run(
      'INSERT INTO payments (id, method, amount, created_at) VALUES (?, ?, ?, ?)',
      [paymentId, input.paymentMethod, totalGross, now]
    )

    // Insert payment allocation (payment → sale)
    run(
      'INSERT INTO payment_allocations (id, payment_id, target_type, target_id, allocated_amount) VALUES (?, ?, ?, ?, ?)',
      [crypto.randomUUID(), paymentId, 'sale', saleId, totalGross]
    )

    // Insert stock movements (negative deltas for each part sold)
    for (const item of input.lineItems) {
      run(
        'INSERT INTO stock_movements (id, part_id, quantity_delta, reason, reference_type, reference_id, created_at) VALUES (?, ?, ?, ?, ?, ?, ?)',
        [crypto.randomUUID(), item.partId, -item.quantity, 'sale', 'sale', saleId, now]
      )
    }

    // Commit transaction
    run('COMMIT')
  } catch (err) {
    // Rollback on any error
    try { run('ROLLBACK') }
    catch {}
    throw err
  }

  // ---------------------------------------------------------------------------
  // Step 6: Fetch and return created entities
  // ---------------------------------------------------------------------------
  const [createdSale] = await db.select().from(sales).where(eq(sales.id, saleId))
  const [createdPayment] = await db.select().from(payments).where(eq(payments.id, paymentId))
  const lineItemRows = await db.select().from(saleLineItems).orderBy(saleLineItems.createdAt)

  return {
    sale: createdSale!,
    payment: createdPayment!,
    lineItems: lineItemRows
  }
}

/**
 * Void a completed sale by setting its status to 'voided'.
 *
 * Does NOT reverse stock movements (per domain rule R13 — voiding accepts error risk).
 * Guards against voiding already-voided sales.
 *
 * @param saleId — ID of the sale to void
 * @returns The updated sale record
 */
export async function voidSale(saleId: string): Promise<typeof sales.$inferSelect> {
  // Check if sale exists and is not already voided
  const existing = await db.select().from(sales).where(eq(sales.id, saleId))

  if (existing.length === 0) {
    throw new SaleNotFoundError(saleId)
  }

  if (existing[0].status === 'voided') {
    throw new Error(`Sale ${saleId} is already voided`)
  }

  // Update status to voided
  const [updated] = await db
    .update(sales)
    .set({ status: 'voided' })
    .where(eq(sales.id, saleId))
    .returning()

  return updated!
}

/**
 * Find a single sale by ID.
 */
export async function findSaleById(id: string) {
  const [result] = await db.select().from(sales).where(eq(sales.id, id))
  return result ?? undefined
}

/** Options for listing sales */
export interface ListSalesOptions {
  /** Maximum number of rows to return (default: 50) */
  limit?: number
  /** Filter by customer ID — null/absent means no filter */
  customerId?: string | null
}

/**
 * List recent sales ordered by creation date (newest first).
 *
 * @param options — Filtering and pagination options
 * @returns Array of sale records sorted newest-first
 */
export async function listSales(options: ListSalesOptions = {}) {
  const { limit = 50, customerId } = options

  const whereClause = customerId ? eq(sales.customerId, customerId) : undefined

  return db
    .select()
    .from(sales)
    .where(whereClause)
    .orderBy(desc(sales.createdAt))
    .limit(limit)
}

/**
 * Get all line items for a sale, ordered by creation.
 */
export async function findLineItemsBySaleId(saleId: string) {
  return db.select().from(saleLineItems).where(eq(saleLineItems.saleId, saleId)).orderBy(asc(saleLineItems.createdAt))
}

/**
 * Get all payments for a sale (via allocations), ordered by creation.
 */
export async function findPaymentsBySaleId(saleId: string) {
  const allocations = await db.select().from(paymentAllocations).where(eq(paymentAllocations.targetId, saleId))
  if (allocations.length === 0) return []

  const paymentIds = allocations.map(a => a.paymentId)
  return db.select().from(payments).where(sql`${payments.id} IN (${sql.join(paymentIds)})`).orderBy(asc(payments.createdAt))
}

/**
 * Get all stock movements referencing a specific sale.
 */
export async function findMovementsBySaleId(saleId: string) {
  return db.select().from(stockMovements).where(eq(stockMovements.referenceId, saleId))
}

